import sys; sys.path.insert(0, sys.argv[1]); from syncer.engine import Syncer; from syncer.store import MemoryStore
def ok(v):
    try:
        Syncer(MemoryStore()).set_interval(v); return True
    except ValueError:
        return False
sys.exit(0 if [ok(v) for v in (10, 86400, 9, 86401, 10**6)] == [True, True, False, False, False] else 1)
